export type ExamBreakdown = {
  key: string;
  label: string;
  earnedPoints: number;
  maxPoints: number;
  percent: number;
};

export type ScholarExam = {
  id: string;
  title: string;
  scope: ScholarScope;
  status: ExamStatus;
  questions: ExamQuestion[];
  rawResponses: ExamRawResponse[];
