  snapshots?: ScholarSnapshot[];
  review?: { version: 1; receipts: import("./learn-quality.ts").ReviewReceipt[]; responses: import("./learn-quality.ts").FindingResponse[] };
  createdAt: string;
  updatedAt: string;
  closedAt?: string;
};

